python3 -c "
import re

IUPAC_MAP = {
    'A': 'A', 'C': 'C', 'G': 'G', 'T': 'T',
    'R': '[AG]', 'Y': '[CT]', 'S': '[GC]', 'W': '[AT]',
    'K': '[GT]', 'M': '[AC]', 'B': '[CGT]', 'D': '[AGT]',
    'H': '[ACT]', 'V': '[ACG]', 'N': '[ACGT]'
}

def iupac_to_regex(pattern):
    return ''.join(IUPAC_MAP.get(c, c) for c in pattern)

motifs = {
    'AP-1': 'TGASTCA',
    'SP1': 'GGGGYGGGG',
    'MYC': 'CACGTG',
    'NF-kB': 'GGGRNNYYCC',
    'CREB': 'TGACGTCA',
    'YY1': 'CCGCCATNTT',
    'CTCF': 'CCACYAGGGGGCGCY',
    'GATA': 'WGATAR',
    'FOXA1': 'TGTTTACY',
    'SRF': 'CCWWWWWWGG'
}

compiled_motifs = {name: re.compile(iupac_to_regex(pat)) for name, pat in motifs.items()}

# Parse human_non_tata.fa
seqs = []
with open('data/human_non_tata.fa', 'r') as f:
    current = []
    for line in f:
        if line.startswith('>'):
            if current:
                seqs.append(''.join(current))
                current = []
        else:
            current.append(line.strip().upper())
    if current:
        seqs.append(''.join(current))

print(f'Parsed {len(seqs)} promoter sequences.')

# Take the central 200bp of the first 1000 sequences
sub_seqs = [s[50:250] for s in seqs[:1000]]

# Count matches
counts = {name: 0 for name in motifs}
for s in sub_seqs:
    for name, regex in compiled_motifs.items():
        if regex.search(s):
            counts[name] += 1

print('Motif frequency in first 1000 promoters (200bp):')
for name, cnt in counts.items():
    print(f'  {name} ({motifs[name]}): {cnt} sequences ({cnt/10:.1f}%)')
"

python3 -c "
import re

IUPAC_MAP = {
    'A': 'A', 'C': 'C', 'G': 'G', 'T': 'T',
    'R': '[AG]', 'Y': '[CT]', 'S': '[GC]', 'W': '[AT]',
    'K': '[GT]', 'M': '[AC]', 'B': '[CGT]', 'D': '[AGT]',
    'H': '[ACT]', 'V': '[ACG]', 'N': '[ACGT]'
}

IUPAC_COMP = {
    'A': 'T', 'C': 'G', 'G': 'C', 'T': 'A',
    'R': 'Y', 'Y': 'R', 'S': 'S', 'W': 'W',
    'K': 'M', 'M': 'K', 'B': 'V', 'D': 'H',
    'H': 'D', 'V': 'B', 'N': 'N'
}

def iupac_to_regex(pattern):
    return ''.join(IUPAC_MAP.get(c, c) for c in pattern)

def get_combined_regex(pattern):
    fwd = iupac_to_regex(pattern)
    rc_pattern = ''.join(IUPAC_COMP[c] for c in pattern[::-1])
    rc = iupac_to_regex(rc_pattern)
    return re.compile(f'({fwd})|({rc})')

motifs = {
    'AP-1': 'TGASTCA',
    'SP1': 'GGGGYGGGG',
    'MYC': 'CACGTG',
    'NF-kB': 'GGGRNNYYCC',
    'CREB': 'TGACGTCA',
    'YY1': 'CCGCCATNTT',
    'CTCF': 'CCACYAGGGGGCGCY',
    'GATA': 'WGATAR',
    'FOXA1': 'TGTTTACY',
    'SRF': 'CCWWWWWWGG'
}

compiled_motifs = {name: get_combined_regex(pat) for name, pat in motifs.items()}

seqs = []
with open('data/human_non_tata.fa', 'r') as f:
    current = []
    for line in f:
        if line.startswith('>'):
            if current:
                seqs.append(''.join(current))
                current = []
        else:
            current.append(line.strip().upper())
    if current:
        seqs.append(''.join(current))

# Sub-seqs: central 200bp
sub_seqs = [s[50:250] for s in seqs if 'N' not in s[50:250]]

with_motif_count = sum(1 for s in sub_seqs if any(regex.search(s) for regex in compiled_motifs.values()))
print(f'Total promoters analysed: {len(sub_seqs)}')
print(f'Promoters containing at least one motif: {with_motif_count} ({with_motif_count/len(sub_seqs)*100:.1f}%)')
"

